public int LengthOfLongestSubstring(string s) {
    var next = new int[128];          // next[c] = индекс последней c + 1; 0 — не встречалась
    int l = 0, best = 0;
    for (int r = 0; r < s.Length; r++) {
        char c = s[r];
        l = Math.Max(l, next[c]);     // прыжок за прошлую c, но никогда назад
        next[c] = r + 1;
        best = Math.Max(best, r - l + 1);
    }
    return best;
}

